<?php
require_once __DIR__.'/config/bootstrap.php';$pageTitle='Your Bag — Ikki';$cart=$_SESSION['cart']??[];$items=[];$subtotal=0;
if($cart){$ids=array_values(array_filter(array_map('intval',array_keys($cart))));if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$st=db()->prepare("SELECT v.id,v.variant_name,v.price,v.stock_quantity,p.name,p.slug,(SELECT image_path FROM product_images WHERE product_id=p.id ORDER BY is_primary DESC,sort_order LIMIT 1) image_path FROM product_variants v JOIN products p ON p.id=v.product_id WHERE v.id IN ($marks) AND v.is_active=1 AND p.is_active=1");$st->execute($ids);foreach($st->fetchAll() as $row){$qty=min((int)$row['stock_quantity'],max(1,(int)$cart[$row['id']]));if($qty<1){unset($_SESSION['cart'][$row['id']]);continue;}$row['quantity']=$qty;$row['line_total']=$qty*(float)$row['price'];$subtotal+=$row['line_total'];$items[]=$row;}}}
require __DIR__.'/includes/header.php';?>
<div class="page-wrap"><div class="page-intro"><span class="eyebrow">YOUR SELECTION / IKKI</span><h1 class="page-title">The bag.</h1><p class="muted">A good choice deserves a beautiful arrival.</p></div><?php if(isset($_GET['added'])):?><div class="notice">Your fragrance has been added to the bag.</div><?php endif;?><?php if(!$items):?><div class="empty-state"><span class="eyebrow">NOTHING HERE, YET</span><h2 style="font:42px var(--serif);color:var(--cream)">Your next signature awaits.</h2><a class="button-gold" href="/shop.php">Explore the collection ↗</a></div><?php else:?><form method="post" action="/actions/cart-update.php"><?=csrf_field()?><div style="overflow-x:auto"><table class="cart-table"><thead><tr><th>Fragrance</th><th>Price</th><th>Quantity</th><th>Line total</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><strong><?=e($item['name'])?></strong><br><small class="muted"><?=e($item['variant_name'])?></small></td><td><?=money($item['price'])?></td><td><input style="max-width:80px" type="number" min="0" max="<?= (int)$item['stock_quantity']?>" name="qty[<?= (int)$item['id']?>]" value="<?= (int)$item['quantity']?>"></td><td><?=money($item['line_total'])?></td></tr><?php endforeach;?></tbody></table></div><div style="display:flex;justify-content:space-between;gap:15px;flex-wrap:wrap;margin-top:20px"><button class="button-outline" type="submit">Update bag</button><a class="text-link" href="/shop.php">Continue exploring ↗</a></div></form><div style="max-width:380px;margin:45px 0 0 auto;padding:25px;background:#1a1915;border:1px solid var(--line)"><span class="eyebrow">YOUR ORDER SUMMARY</span><p style="display:flex;justify-content:space-between;margin:20px 0">Subtotal <strong><?=money($subtotal)?></strong></p><p class="muted" style="font-size:11px">Delivery charges, if applicable, are confirmed at checkout.</p><a class="button-gold" style="width:100%" href="/checkout.php">Continue to details <span>↗</span></a></div><?php endif;?></div><?php require __DIR__.'/includes/footer.php';?>